// Redact common secrets, then prepare a short log row.
// Never send the raw error payload to a database, email, or chat.
const cfg = $('Set your IDs').first().json;
// Read from the Error trigger, not $input: "Set your IDs" does not pass the error payload through.
const raw = $('Error trigger').first().json;

function redact(value) {
  let s = typeof value === 'string' ? value : JSON.stringify(value, null, 2);
  const patterns = [
    /sk-[A-Za-z0-9_-]{16,}/g,
    /xox[baprs]-[A-Za-z0-9-]{10,}/g,
    /Bearer\s+[A-Za-z0-9._\-+/=]+/gi,
    /-----BEGIN [A-Z ]+PRIVATE KEY-----[\s\S]*?-----END [A-Z ]+PRIVATE KEY-----/g,
    /ntn_[A-Za-z0-9]+/g,
    /secret_[A-Za-z0-9]+/g,
    /(api[_-]?key|client_secret|access_token|refresh_token|password|authorization)\s*[:=]\s*(?:\\["']|["'])?[^"'\\\s]+(?:\\["']|["'])?/gi,
  ];
  for (const re of patterns) s = s.replace(re, '[REDACTED]');
  // Truncate so a huge stack cannot become the log
  if (s.length > 4000) s = s.slice(0, 4000) + '\n… [truncated]';
  return s;
}

const exec = raw.execution || raw;
const err = exec.lastNodeExecuted
  ? `${exec.lastNodeExecuted}: ${exec.error?.message || raw.message || 'error'}`
  : (raw.message || raw.error?.message || 'Workflow error');

const redacted = redact({
  workflowName: exec.workflowId ? '[id omitted]' : undefined,
  lastNode: exec.lastNodeExecuted || raw.lastNodeExecuted,
  message: err,
  errorMessage: exec.error?.message || raw.error?.message,
  // Do not include exec.data or request bodies
});

return [{
  json: {
    ...cfg,
    title: `Error: ${String(err).slice(0, 120)}`,
    body: redacted,
    subject: 'Redacted workflow error (Agent Desk)',
    briefMarkdown: [
      'A linked workflow failed. This note is redacted and truncated.',
      '',
      redacted,
      '',
      'Do not paste raw execution data into this log.',
    ].join('\n'),
  }
}];
